<?php
namespace Joomla\Component\Blog\Administrator\Controller;
defined('_JEXEC') or die;
use Joomla\CMS\Factory; use Joomla\CMS\MVC\Controller\BaseController; use Joomla\CMS\Router\Route; use Joomla\CMS\Session\Session; use Joomla\Component\Blog\Administrator\Helper\CategoriesHelper;
final class CategoriesController extends BaseController { public function save():void{Session::checkToken()or jexit('Invalid token');$app=Factory::getApplication();if(!$app->getIdentity()->authorise('core.manage','com_blog'))throw new \RuntimeException('Not authorised',403);$id=CategoriesHelper::save($app->getInput()->post->get('jform',[],'array'));$app->enqueueMessage('Category saved.');$app->redirect(Route::_('index.php?option=com_blog&view=categories&category_id='.$id,false));} public function delete():void{Session::checkToken()or jexit('Invalid token');$app=Factory::getApplication();if(!$app->getIdentity()->authorise('core.delete','com_blog'))throw new \RuntimeException('Not authorised',403);$id=$app->getInput()->post->getInt('id');$db=CategoriesHelper::db();$db->setQuery('UPDATE #__blog SET catid=0 WHERE catid='.(int)$id)->execute();$db->setQuery('DELETE FROM #__blog_categories WHERE id='.(int)$id)->execute();$app->enqueueMessage('Category deleted. Posts were left uncategorised.');$app->redirect(Route::_('index.php?option=com_blog&view=categories',false));}}
